r_ctrl = primitives.call(name="observe_maniskill_control_state")
r_inst = primitives.call(name="list_maniskill_instances", min_pixel_count=5)
r_state = primitives.call(name="observe_maniskill_state")

if r_ctrl.ok:
    print("ctrl:", r_ctrl.output)
if r_state.ok:
    print(
        "state keys:",
        list(r_state.output.keys()),
        "goal_xyz:",
        r_state.output.get("goal_xyz"),
    )
if r_inst.ok:
    for inst in r_inst.output.get("instances", []):
        print("inst:", inst)
